224:{
225:    struct proxy_header_v2 *hdr = (struct proxy_header_v2 *)buffer;
226:    size_t proto_signature_length = sizeof(proxy_v2_sig) - 1;
227:    size_t size;
228:    struct lwan_proxy *const proxy = request->proxy;
229:
230:    if (memcmp(buffer, proxy_v2_sig, proto_signature_length))
231:        return NULL;
232:
233:    size = proto_signature_length + (unsigned int)ntohs(hdr->len);
234:    if (UNLIKELY(size > (unsigned int)sizeof(*hdr)))
235:        return NULL;
236:
237:    if (hdr->cmd_ver != 0x21)
238:        return NULL;
239:
240:    if (hdr->fam == 0x11) {
241:        memcpy(&proxy->from.ipv4, &hdr->addr.ip4.src, sizeof(hdr->addr.ip4.src));
242:        memcpy(&proxy->to.ipv4, &hdr->addr.ip4.dst, sizeof(hdr->addr.ip4.dst));
243:    } else if (hdr->fam == 0x21) {
244:        memcpy(&proxy->from.ipv6, &hdr->addr.ip6.src, sizeof(hdr->addr.ip6.src));
245:        memcpy(&proxy->to.ipv6, &hdr->addr.ip6.dst, sizeof(hdr->addr.ip6.dst));
246:    }
247:
248:    return buffer + size;
249:}
