302:    if (!strcmp(token, "TCP4")) {
303:        proxy->from.ipv4.sin_port = htons((unsigned short)strtoul(src_port, NULL, 10));
304:        proxy->from.ipv4.sin_family = AF_INET;
305:        proxy->from.ipv4.sin_addr.s_addr = INADDR_ANY;
306:        proxy->to.ipv4.sin_port = htons((unsigned short)strtoul(dst_port, NULL, 10));
307:        proxy->to.ipv4.sin_family = AF_INET;
308:        proxy->to.ipv4.sin_addr.s_addr = INADDR_ANY;
309:    } else {
