311:        proxy->from.ipv6.sin6_family = AF_INET6;
312:        proxy->to.ipv6.sin6_port = htons((unsigned short)strtoul(dst_port, NULL, 10));
313:        proxy->to.ipv6.sin6_family = AF_INET6;
314:    }
